import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

test.describe('רכישת כרטיס לאירוע', () => {
  test('כשל רשת בטעינת האירוע — "לא הצלחנו לטעון את האירוע" ו"נסו שוב" @android @prod-safe #6a86f7bc4808', async ({ page }) => {
    test.setTimeout(120_000);

    // 1. חסימת הרשת ל-REST ופתיחת האירוע
    await page.route('**/rest/v1/**', (route) => route.abort());
    await page.goto('/events/087e8dd0-3043-4e55-b182-c2b646c7b7f8');

    // 2. לחכות למצב השגיאה (מופיע אחרי ~24 שניות)
    await expect(page.getByText('לא הצלחנו לטעון את האירוע')).toBeVisible({ timeout: 45_000 });
    await expect(page.getByText('בדקו את החיבור לאינטרנט ונסו שוב.')).toBeVisible();
    const retry = page.getByRole('button', { name: 'נסו שוב' });
    await expect(retry).toBeVisible();

    // 3. הסרת החסימה ו"נסו שוב"
    await page.unroute('**/rest/v1/**');
    await retry.click();
    await expect(page.getByText('QA 08.10 אירוע', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'קניית כרטיס' })).toBeAttached();
  });
});
